def determine_interpreter_file_name() -> str:
    """
    Determine the interpreter file name based on the Python implementation and OS.

    :raises SystemExit: If the Python implementation is unsupported.
    :return: The file name of the Python interpreter.
    """
    implementations: dict[str, Callable[[], str]] = {
        "PyPy": lambda: "pypy3.exe" if os.name == "nt" else "pypy3",
        "CPython": lambda: "python.exe" if os.name == "nt" else "python",
    }
    python_implementation = platform.python_implementation()

    try:
        return implementations[python_implementation]()
    except KeyError:
        print(f"Unsupported Python implementation {python_implementation}", file=sys.stderr)  # noqa: T201
        raise SystemExit(1) from None
